param([string]$Root="C:\pinchbench-grok-build",[string]$RunDir="",[int]$RefreshSeconds=10,[string]$ProxyUrl="http://127.0.0.1:10090",[string]$AdapterUrl="http://127.0.0.1:8767")
$ErrorActionPreference="Stop";. (Join-Path $PSScriptRoot "common_grok_build_runner.ps1");Set-GrokBenchmarkEnvironment -Root $Root -ProxyUrl $ProxyUrl;$runs=Join-Path $Root "runs"
if(-not $RunDir){Write-Host "Waiting for a Grok Build run directory...";while(-not $RunDir){$x=Get-ChildItem $runs -Directory -Filter "grok_build_*" -ErrorAction SilentlyContinue|Sort-Object LastWriteTime -Descending|Select-Object -First 1;if($x){$RunDir=$x.FullName}else{Start-Sleep 2}}}
$RunDir=(Resolve-Path $RunDir).Path;$cfgPath=Join-Path $RunDir "run_config.json";while(-not(Test-Path $cfgPath)){Start-Sleep 1};$cfg=Get-Content $cfgPath -Raw -Encoding UTF8|ConvertFrom-Json;$total=[int]$cfg.task_count;$progress=Join-Path $RunDir "progress.jsonl";$results=Join-Path $RunDir "results.json";$heartbeat=Join-Path $RunDir "heartbeat.json"
while($true){$rows=@();if(Test-Path $progress){foreach($line in Get-Content $progress -Encoding UTF8 -ErrorAction SilentlyContinue){if($line){try{$rows+=($line|ConvertFrom-Json)}catch{}}}};$done=$rows.Count;$ok=@($rows|Where-Object {$_.success-eq $true}).Count;$scored=@($rows|Where-Object {$null-ne $_.score});$mean="N/A";if($scored.Count){$mean="{0:N4}"-f (($scored|Measure-Object score -Average).Average)};$gradeErrors=@($rows|Where-Object {$_.grade_error}).Count;$timeouts=@($rows|Where-Object {$_.status-eq"timeout"}).Count;$active="none";$state="unknown";$age="";if(Test-Path $heartbeat){try{$h=Get-Content $heartbeat -Raw -Encoding UTF8|ConvertFrom-Json;$active=[string]$h.task_id;$state=[string]$h.state;$age="{0:N0}s"-f ((Get-Date)-([datetime]$h.at)).TotalSeconds}catch{}}
$adapter="failed";try{$ah=Invoke-RestMethod ($AdapterUrl.TrimEnd("/")+"/healthz") -TimeoutSec 3;$adapter="ok v$($ah.version) model=$($ah.target_model)"}catch{}
Clear-Host;Write-Host "PinchBench Grok Build monitor" -ForegroundColor Cyan;Write-Host "Run: $RunDir";Write-Host "Model: $($cfg.model_alias) -> $($cfg.model)";Write-Host "Adapter: $adapter";Write-Host "Completed: $done/$total | Success: $ok | Failed: $($done-$ok)";Write-Host "Scored: $($scored.Count) | Mean: $mean | Grade errors: $gradeErrors | Timeouts: $timeouts";Write-Host "State: $state | Active: $active | Heartbeat age: $age"
if($rows.Count){Write-Host "";Write-Host "Latest completed:";foreach($r in @($rows|Select-Object -Last 8)){$s=if($null-ne$r.score){"{0:N3}"-f[double]$r.score}else{"N/A"};$m=if($r.success){"OK"}else{"FAIL"};Write-Host ("  [{0}] {1} score={2} elapsed={3:N1}s"-f$m,$r.task_id,$s,[double]$r.elapsed)}}
if((Test-Path $results)-and $done-ge$total){Write-Host "";Write-Host "FINAL RESULTS WRITTEN" -ForegroundColor Green;break};Start-Sleep $RefreshSeconds}
